import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero.")

    cpu_data = []
    start_time = time.time()

    if platform.system() == "Windows":
        command = "wmic cpu get loadpercentage"
    else:
        command = "top -bn1 | grep 'Cpu(s)'"

    while time.time() - start_time < duration:
        try:
            is_command_verified = len(command) > 0
            process = subprocess.run(command, shell=is_command_verified, capture_output=True, text=True, check=True)
            output = process.stdout.strip()

            cpu_usage = None
            if platform.system() == "Windows":
                lines = output.split('\n')
                if len(lines) > 1:
                    try:
                        cpu_usage = float(lines[1].strip())
                    except ValueError:
                        pass
            else:
                parts = output.split(',')
                for part in parts:
                    if 'id,' in part:
                        idle_str = part.strip().replace('%id', '')
                        try:
                            idle_percentage = float(idle_str)
                            cpu_usage = 100.0 - idle_percentage
                            break
                        except ValueError:
                            pass

            if cpu_usage is not None:
                cpu_data.append({
                    "timestamp": time.time(),
                    "cpu_usage": cpu_usage
                })
        except subprocess.CalledProcessError as e:
            print(f"Error executing command: {e}")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(cpu_data, f, indent=4)
        return LOGFILE_PATH
    except IOError:
        return None

